INSERT INTO `form_manager` (`id`, `slug`, `table_name`, `title`, `description`, `roles`, `react_route`, `submit_endpoint`, `http_method`, `status`, `version`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 'form-constructor', 'form_manager', 'Construtor de Formulários', 'Meta-formulário: cada grupo abaixo define os campos de uma das quatro tabelas do módulo Form. Preencha de cima para baixo — o formulário alimenta o grupo, o grupo alimenta a linha, a linha alimenta o campo.', 'admin', '/v1/form-constructor', '/api/v1/form-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(2, 'usuario-autenticacao', 'user_manager', 'Usuário (Autenticação)', 'Tela de Login do Usuário', NULL, '/v1/user-auth', '/api/v1/auth', 'POST', 'draft', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(3, 'cadastro-usuario', 'user_manager', 'Usuário (Segurança)', 'Primeira etapa de cadastro de usuários.', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(4, 'dados-do-usuario', 'user_profiles', 'Usuário (Dados)', 'Cadastro da segunda etapa do Formulário', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-profiles/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(6, 'list-constructor', 'list_manager', 'Construtor de Listagens', 'Meta-formulário: cada grupo abaixo define os campos de uma das três tabelas do módulo List. Preencha de cima para baixo — o formulário alimenta a listagem, a listagem alimenta as colunas e as ações.', 'admin', '/v1/list-constructor', '/api/v1/list-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(7, 'cadastro-nav', 'nav_manager', 'Nav (Casca do App)', 'Cadastro da casca de navegação: nome, imagem, ícone de mensagens e versão do sistema exibidos na navbar.', '["admin"]', '/v1/nav-manager/create', '/api/v1/nav-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(8, 'cadastro-menu', 'menu_manager', 'Item de Menu', 'Cadastro de item de navegação — pertence a um Nav e pode ter um item pai (submenu).', '["admin"]', '/v1/menu-manager/create', '/api/v1/menu-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(9, 'atualizar-upload', 'uploads', 'Upload (Metadados)', 'Edição dos metadados de um arquivo já enviado — título, descrição, categoria e status. Não cria upload novo (isso é feito pelo envio multipart, fora do módulo Form).', '["admin"]', '/v1/upload-manager/update', '/api/v1/upload-manager/update', 'PUT', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(10, 'cadastro-route', 'route_manager', 'Rota', 'Cadastro manual de uma rota — uso: registrar rota externa que a introspecção automática de Config/Routes.php não captura.', '["admin"]', '/v1/route-manager/create', '/api/v1/route-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(11, 'cadastro-role', 'user_roles', 'Perfil de Acesso', 'Cadastro de perfil de acesso (role) — nome, slug, descrição e permissões.', '["admin"]', '/v1/user-roles/create', '/api/v1/user-roles/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
