	(27, 'criar-sala-chat', 'chat_rooms_manager', 'Nova Sala de Chat', 'Criacao de uma sala de chat. O aceite de responsabilidade pela moderacao e obrigatorio.', '["user","admin"]', '/v1/chat-rooms-manager/create', '/api/v1/chat-rooms-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
