	(30, 'criar-membro-sala', 'chat_room_members', 'Novo Membro de Sala', 'Adiciona um usuario a uma sala de chat (somente o dono da sala ou admin).', '["user","admin"]', '/v1/chat-room-members/create', '/api/v1/chat-room-members/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
