	(33, 'editar-anexo-chat', 'chat_room_attachments', 'Editar Anexo', 'Atualizacao dos metadados de um anexo de chat — status e categoria (arquivo e mensagem sao imutaveis).', '["user","admin"]', '/v1/chat-room-attachments/update', '/api/v1/chat-room-attachments/update', 'PUT', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
