	(37, 'editar-advertencia', 'chat_room_warnings', 'Editar Advertência', 'Corrige a palavra registrada na advertência (só admin).', '["admin"]', '/v1/chat-room-warnings/update', '/api/v1/chat-room-warnings/update', 'PUT', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(38, 'criar-favorito', 'chat_room_favorites', 'Favoritar Sala', 'Marca uma sala como favorita para você.', '["user", "admin"]', '/v1/chat-room-favorites/create', '/api/v1/chat-room-favorites/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(39, 'editar-favorito', 'chat_room_favorites', 'Trocar Sala Favorita', 'Troca a sala favorita por outra. Só o dono do favorito.', '["user", "admin"]', '/v1/chat-room-favorites/update', '/api/v1/chat-room-favorites/update', 'PUT', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(40, 'denunciar-anexo', 'chat_room_attachment_reports', 'Denunciar Anexo', 'Denuncia um anexo de mensagem. O anexo e o autor são bloqueados na hora.', '["user", "admin"]', '/v1/chat-room-attachment-reports/create', '/api/v1/chat-room-attachment-reports/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
	(41, 'criar-mensagem-direta', 'messages_manager', 'Nova Mensagem', 'Envia uma mensagem a um usuário, agora ou em data e hora programadas.', '["admin"]', '/v1/messages-manager/create', '/api/v1/messages-manager/create', 'POST', 'active', 1, '2026-10-06 10:27:05', '2026-10-06 19:53:37', NULL),
