	(21, 'timeline-manager', 'view_timeline_manager', 'Linhas do Tempo', 'Listagem das linhas do tempo (timelines) cadastradas.', '/api/v1/timeline-manager-view/get-all', '/api/v1/timeline-manager-view/search', '["user","admin"]', 'created_at', 'desc', 20, NULL, 'active', 1, '2026-10-06 10:27:05', '2026-10-06 10:27:05', NULL),
